-- Insert English translations linking back to the original Vietnamese posts
INSERT INTO post_translations (post_id, locale, title, slug, excerpt, content, meta_title, meta_description, created_at, updated_at)
SELECT 
  id, 
  'en-US',
  'OpenClaw and the Moment AI Crosses the Control Line',
  'openclaw-and-the-moment-ai-crosses-the-control-line',
  'Are we truly ready for AI to stop being a mere observer and start acting directly within our own systems?',
  '<p>To this day, artificial intelligence is no longer a distant concept—it has quietly permeated every corner of our lives. And then OpenClaw appeared, forcing me to pause and reflect: are we truly ready for AI to stop being a mere observer and start acting directly within our own systems?</p><p>In the past, AI felt safe. It answered questions, suggested ideas, even wrote on our behalf—but always from behind an invisible wall. Control remained firmly in human hands. That certainty, however, begins to erode when AI agents like this can open browsers, read files, send messages, and operate directly on a computer. At that point, the question is no longer how intelligent AI is, but whether we are prepared to entrust it with real authority. OpenClaw is a vivid illustration of how thin that boundary has become.</p><p>My advice is simple: don’t grant full permissions too quickly, no matter how tempting it may be. What sets OpenClaw apart is not its conversational ability or the model behind it, but the fact that it is designed to access the entire system without protective layers—no sandbox, no hard guardrails. If you allow it, it will act as you would. That is a significant leap forward—and a risky one.</p><p>From my experience, when working with any new “agent,” human or machine, the most critical factor is not speed or initial efficiency, but understanding. You need to know how it interprets instructions, how it reacts to gaps in context, and, most importantly, how it fails. Granting full control to an AI before understanding these aspects is no different from throwing a new hire straight into a production environment on day one. The risk rarely comes from malicious intent, but from immature design and our own misplaced expectations.</p><figure><img src="/images/openclaw_detail_1.png" alt="Illustration 1" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><p>Execution capability does not always correlate with reliability. In hands-on tests with OpenClaw, I’ve seen it handle a wide range of tasks: opening browsers, checking broken links, interacting with user interfaces, even communicating via Telegram. For simple, repetitive tasks, the initial impression is genuinely strong. But over time, reality becomes clearer: it still needs step-by-step guidance, rarely shows true initiative, and tends to stop at “knowing how to do something” rather than “knowing when it should be done.”</p><p>This is not a failure—it’s a reminder that today’s AI agents are closer to highly empowered interns than to truly independent colleagues. If you expect more, disappointment is inevitable. I’ve seen the same pattern with many tools before: bold promises of transformation, followed by the enduring need for human direction.</p><figure><img src="/images/openclaw_detail_2.png" alt="Illustration 2" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><p>For me, security is not an optional feature; it is a core responsibility. OpenClaw is refreshingly candid in labeling itself as “risky,” clearly warning users about permission grants and advising that only those with security expertise should proceed. That honesty is commendable, but it also means the burden is squarely on us. When AI can touch browsers, accounts, files, and communication channels, the distance between a minor mistake and a major incident is razor-thin. In that context, the smartest approach is not perfect prompting, but strict isolation: separate machines, separate accounts, non-sensitive data. Without isolation, AI autonomy stops being creative and becomes a gamble.</p><p>Ultimately, execution will never replace thinking. OpenClaw excels as an action-oriented tool, but it cannot take on strategy, prioritization, or judgment in ambiguous situations. Most real-world work isn’t hard because of operations—it’s hard because of complex context. Until AI learns “what not to do” as well as “what to do,” humans must remain in the driver’s seat—not just supervising, but shaping direction.</p><figure><img src="/images/openclaw_detail_3.png" alt="Illustration 3" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><p>OpenClaw is neither a failure nor the pinnacle of AI agents. It is a realistic snapshot of the transitional phase we are living through: from passive AI to AI with the power to act. Its true value lies in the questions it raises: how much authority are we willing to give AI, and under what conditions? That is not merely a technical question—it is a question of responsibility. Our responsibility to ourselves, and to the world we are in the process of building.</p>',
  'OpenClaw and the Moment AI Crosses the Control Line',
  'Are we truly ready for AI to stop being a mere observer and start acting directly within our own systems?',
  NOW(), NOW()
FROM posts WHERE slug = 'openclaw-va-khoanh-khac-ai-vuot-qua-ranh-gioi-kiem-soat'
ON CONFLICT (post_id, locale) DO UPDATE SET
  title = EXCLUDED.title, slug = EXCLUDED.slug, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content;

INSERT INTO post_translations (post_id, locale, title, slug, excerpt, content, meta_title, meta_description, created_at, updated_at)
SELECT 
  id, 
  'en-US',
  'AI in the IT Era: Do We Still Need to Learn Programming?',
  'ai-in-the-it-era-is-learning-to-code-still-necessary',
  'History shows a recurring pattern. Every major technological leap forces society to ask the same fundamental question. AI in IT is no exception.',
  '<p>Never before in the history of the IT industry has the question “Do we still need to learn programming?” been asked so frequently—and so anxiously. It is no longer just students at the beginning of their careers who are asking it. Engineers with 7–10 years of experience are asking it. Engineering managers who see AI writing code faster than their teams are asking it. Founders, quietly recalculating headcount and cost structures, are asking it too.</p><p>This question does not come from laziness. It comes from a collapse of certainty—the long-held belief that “being good at programming” guarantees a stable, long-term career in tech.</p><p>To answer this question honestly, we must avoid two dangerous extremes:<br>- Panic: AI will kill programmers.<br>- Denial: AI is just another tool; nothing really changes.</p><p>As usual, the truth lies much deeper.</p><figure><img src="/images/bai21.png" alt="Illustration 1" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><h3>1. Every technological revolution redefines human value</h3><p>History shows a recurring pattern. Every major technological leap forces society to ask the same fundamental question.<br>- When mechanical looms appeared: Do we still need weavers?<br>- When spreadsheets became widespread: Do we still need manual accountants?<br>- When low-code platforms emerged: Do we still need developers?</p><p>What’s interesting is this: humans rarely disappear from the system. But their roles are relentlessly redefined.</p><p>AI in IT is no exception. It does not end programming—it ends a narrow, outdated interpretation of programming.</p><h3>2. The real issue is not that AI can write code, but that code itself has become commoditized</h3><p>In economics, when something becomes: Easy to produce - Cheap - Easily replicated - Undifferentiated… its value collapses.</p><p>Code is following this exact trajectory. Today:<br>- Writing a REST API is no longer a rare skill<br>- Building a CRUD UI offers little competitive advantage<br>- Copying “best-practice” architectures no longer guarantees success</p><p>AI did not start this trend. It simply accelerated it. This leads to an uncomfortable truth for many in the industry: Knowing how to write code is no longer the same as creating value.</p><figure><img src="/images/bai23.png" alt="Illustration 2" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><h3>3. But IT was never really about code</h3><p>When systems fail, the reason is almost never “Because the syntax was wrong.” Much more often, it’s because:<br>- The problem was misunderstood<br>- The abstractions were poorly designed<br>- Complexity was underestimated during scale<br>- Short-term technical decisions were made under deadline pressure<br>- User behavior was misunderstood</p><p>These failures do not live in code. They live in thinking that happens before code is written.</p><p>AI can generate code for you—but:<br>- It does not bear responsibility when decisions are wrong<br>- It does not live with the consequences of bad architecture two years later<br>- It does not have to explain to the business why the system cannot be “fixed quickly”</p><p>Put bluntly: AI has no accountability.</p><h3>4. Programming is how humans learn to think precisely</h3><p>One of the most overlooked reasons programming still matters—perhaps more than ever—is this: Programming trains the mind.</p><p>Learning programming teaches you how to:<br>- Decompose complex problems<br>- Think in cause-and-effect chains<br>- Manage state and transformation<br>- Accept that systems are never perfect</p><p>People who have never learned programming seriously often struggle to: Work with large, interconnected systems, ask the right questions of AI, or judge whether AI output is “good enough” or dangerously wrong. This creates a paradox: The more you rely on AI, the more essential a solid programming foundation becomes.</p><h3>5. AI is exposing an uncomfortable truth in the IT industry</h3><p>For years, the industry has tolerated a class of engineers who: Know frameworks but lack depth, memorize patterns without understanding why they exist, perform well with clear specs but collapse in ambiguity.</p><p>AI exposes this mercilessly. When AI can generate code, refactor, write tests, suggest architectures… the remaining human work lies in decision-making under uncertainty. And not everyone in IT is prepared for that.</p><h3>6. The IT industry will polarize—more, not less</h3><p>AI will not eliminate programmers. It will amplify the gap between them:<br>- Those who deeply understand systems will leverage AI to move faster<br>- Those who only follow instructions will be replaced or pushed into lower-value roles</p><p>The future market will not lack people who “can code.” It will lack people who understand why the code should exist at all.</p><h3>7. So how should we learn programming in the AI era?</h3><p>The answer is not “learn more languages.” It is learn deeper, more abstractly. Learn:<br>- System design principles<br>- Architectural thinking<br>- Technical trade-offs<br>- How AI systems work—and where they fail<br>- How to control, review, and take responsibility for AI output</p><p>Programming is no longer about typing code. It is about: Conducting a disciplined dialogue with machines, grounded in responsibility.</p><h3>8. The real question: where do you want to stand in the value chain?</h3><p>AI forces every IT professional to confront a deeply personal question: Do I want to make decisions—or merely execute them?</p><p>If your goal is to: Receive tasks, implement instructions, avoid responsibility for the bigger picture… then yes, AI will steadily narrow that path.</p><p>But if you aim to: Understand the true nature of problems, shape solutions, take ownership of systems and their impact on people… then programming remains an irreplaceable foundation.</p><h3>Conclusion</h3><p>AI does not make IT easier. It simply removes the places where superficial understanding can hide.</p><p>Learning programming still matters. But not to become a faster typist—to become a clearer thinker.</p><p>Perhaps this is programming’s return to its most meaningful role: A discipline that enables humans to understand, design, and take responsibility for complex systems.</p>',
  'AI in the IT Era: Do We Still Need to Learn Programming?',
  'History shows a recurring pattern. Every major technological leap forces society to ask the same fundamental question.',
  NOW(), NOW()
FROM posts WHERE slug = 'ai-trong-thoi-dai-it-lieu-co-con-can-hoc-lap-trinh'
ON CONFLICT (post_id, locale) DO UPDATE SET
  title = EXCLUDED.title, slug = EXCLUDED.slug, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content;

INSERT INTO post_translations (post_id, locale, title, slug, excerpt, content, meta_title, meta_description, created_at, updated_at)
SELECT 
  id, 
  'en-US',
  'AI is making building cheaper — and that''s the real issue.',
  'ai-is-making-building-cheaper-and-thats-the-real-issue',
  'Building a product has never been easier. Building a product worth existing has never been harder.',
  '<p>We are entering a paradoxical era in technology:</p><p>Building a product has never been easier. Building a product worth existing has never been harder.</p><p>AI, no-code and low-code platforms, cloud infrastructure, and open-source ecosystems are all doing the same thing at once: driving the technical barrier to entry close to zero.</p><p>Today, a single person with a laptop and a handful of AI tools can: Build an MVP in days, deploy production-grade systems without an infrastructure team, generate landing pages, content, and even pitch decks.</p><p>And that reality forces an uncomfortable question: When anyone can build a product, where does real competitive advantage come from?</p><h3>1. "Being able to build" is no longer an advantage — it''s the entry ticket</h3><p>In the past, building a product itself was a moat: You needed strong engineering talent, you needed capital, you needed time.</p><p>Today, being able to build is merely the price of admission. If your competitive narrative still relies on: "We build fast", "We use cutting-edge technology", "We''re AI-powered"… then you are competing at the lowest layer—the very layer AI is designed to flatten.</p><h3>2. When speed stops being a weapon, it becomes a trap</h3><p>Many teams pride themselves on: Extremely short time-to-market, frequent releases, feature-heavy roadmaps. But in a world where everyone moves fast, speed no longer differentiates.</p><p>Worse, it creates a dangerous illusion: build fast → learn slowly → die early.</p><p>Products rarely fail because they were built too slowly. They fail because: They solved the wrong problem, they solved the right problem for the wrong users, they solved the right problem for the right users at the wrong time. None of these can be accelerated by AI.</p><h3>3. Competitive advantage is shifting from execution to insight</h3><p>When execution becomes cheap, insight becomes expensive.</p><p>Insight is not: A clever idea, a novel feature. Real insight means: Understanding a pain point others only see superficially, recognizing constraints the market ignores, grasping real user behavior—not slide-deck abstractions.</p><p>AI can synthesize information. It cannot live inside a customer''s reality. It does not suffer the consequences of being wrong. True insight is earned through direct exposure to reality.</p><figure><img src="/images/bai3.png" alt="Illustration 1" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><h3>4. Strong products don''t win on features — they win on positioning</h3><p>In a market where features can be copied almost instantly, the real question is no longer: "What does your product do?". But: "Why does this product exist—and exactly who is it for?".</p><p>Many products fail not because they are bad, but because: They tell no clear story, they have no specific enemy to fight, they refuse to exclude most of the market. Modern competition is a battle for mindshare, not functionality.</p><h3>5. The hardest thing to copy isn''t technology — it''s the organization</h3><p>Technology can be cloned. UI can be copied. Features can be reverse-engineered.</p><p>What is extremely difficult to replicate is: How a team makes decisions, how it prioritizes under conflict, its culture of trade-offs, its ability to learn from real failure.</p><p>AI cannot build a learning organization for you. In the long run, the organization becomes the product.</p><h3>6. When everyone can build, the winners are those who dare not to</h3><p>One of the greatest paradoxes of the AI era is this: The ability to not build becomes a strategic advantage.</p><p>Knowing when to: Not add another feature, not chase trends, not comply with every customer request… requires clarity and discipline that very few teams possess. AI helps you build everything. Only humans can decide what should not exist.</p><figure><img src="/images/bai32.png" alt="Illustration 2" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><h3>7. Future competition is a game of conviction, not noise</h3><p>As products become easier to build, markets become louder: More launches, more announcements, more "AI-powered" claims.</p><p>In this noise, advantage does not belong to the loudest voice, but to the team that: Stays in the game long enough, maintains a clear value axis, preserves identity while scaling.</p><p>Conviction becomes a new kind of moat—one that AI cannot manufacture for you.</p><h3>Conclusion</h3><p>When anyone can build a product, building is no longer a strategic question.</p><p>The real questions are: How deeply do you understand your market? What are you brave enough to exclude? Are you building an organization that learns—or merely one that ships?</p><p>AI makes products easier to create. But that is precisely why only products with a strong reason to exist will survive.</p><p>In a world where anyone can build, the winners won''t be those who build best—but those who understand which game they are actually playing.</p>',
  'AI is making building cheaper — and that''s the real issue.',
  'Building a product has never been easier. Building a product worth existing has never been harder.',
  NOW(), NOW()
FROM posts WHERE slug = 'ai-khien-viec-build-tro-nen-re-va-do-moi-la-van-de'
ON CONFLICT (post_id, locale) DO UPDATE SET
  title = EXCLUDED.title, slug = EXCLUDED.slug, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content;

INSERT INTO post_translations (post_id, locale, title, slug, excerpt, content, meta_title, meta_description, created_at, updated_at)
SELECT 
  id, 
  'en-US',
  'Tokens in AI: Understanding the "Currency" of Artificial Intelligence',
  'tokens-in-ai-understanding-the-currency-of-artificial-intelligence',
  'From data processing to operational costs, tokens are shaping an entirely new economic ecosystem. Explore what tokens are, why the term "Token Economy" matters, and who may emerge as the winners in this race.',
  '<p>In today''s rapidly expanding AI landscape, the concept of a token has become ubiquitous—yet not everyone fully understands its significance. From data processing to operational costs, tokens are shaping an entirely new economic ecosystem. This article explores what tokens are, how many are required for various AI tasks, why the term "Token Economy" is increasingly relevant, the staggering scale of token "burn," and ultimately, who may emerge as the winners in this race.</p><h2>What Is a Token?</h2><p>In the context of AI—particularly with Large Language Models (LLMs) such as OpenAI''s GPT series, xAI''s Grok, or Meta''s LLaMA—a token is not a cryptocurrency unit as in blockchain systems. Instead, it is the most fundamental unit used to process textual input and output.</p><p>Think of your text as being segmented into smaller pieces. A token may represent:<br>- A full word (e.g., "apple"),<br>- A subword unit (e.g., "un" in "understand"),<br>- Or even a punctuation mark or special character.</p><p>AI models use tokens to encode and predict data. For example, the sentence "Hello, world!" may be divided into approximately 3–4 tokens, depending on the tokenizer (the tool responsible for token segmentation).</p><p>Why are tokens critical? Because LLMs operate on a transformer architecture, where each token is processed in relation to others within a contextual window. The total number of tokens directly determines computational complexity, processing cost, and output quality. Companies such as OpenAI and xAI measure AI resource consumption in tokens.</p><h2>Token Consumption Across AI Tasks</h2><p>A defining characteristic of modern AI systems is that computational cost—and therefore token usage—scales non-linear. Using a basic text chat as a 1x baseline:</p><ul><li>Standard text chat → ~1x token usage (short prompt, short response).</li><li>Image understanding or generation → ~10x (images are divided into thousands of patches, each converted into tokens).</li><li>Advanced reasoning models (e.g., chain-of-thought, o1-style reasoning) → 100x or more (internal reasoning generates large volumes of hidden tokens before producing the final output).</li><li>Short video generation (~10 seconds) → up to 3,000x (video frames are tokenized similarly to images, resulting in extremely long sequences).</li><li>Deep research / agentic workflows → easily 1,000,000x or more (multiple tool calls, web searches, iterative refinement, long context windows, retries—all multiplying token burn).</li></ul><figure><img src="/images/bai4-2.png" alt="Illustration 1" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><p><strong>Simple tasks (basic chat):</strong> A short query like "What''s the weather today?" may consume 10–20 input tokens and a similar number for output—typically under 50 tokens total.</p><p><strong>Medium-complexity tasks (blog writing, summarization):</strong> Writing a 500-word blog post may require 500–1,000 input tokens (depending on prompt detail) and up to 1,000 output tokens.</p><p><strong>Complex tasks (data analysis, code generation):</strong> Processing a 10,000-word document or training a model can consume millions of tokens. Fine-tuning a model may require billions of tokens from training datasets.</p><p>AI services are priced per token. Providers charge per million tokens (e.g., $X per million input tokens and $Y per million output tokens). Tokens thus become a measurable unit of digital productivity—quantifying how much "thinking" or "work" an AI system performs per resource unit.</p><h2>Tokens as a Substitute for Human Labor — The Emergence of a True Token Economy</h2><p>Consider the productivity leap: A deep research task that previously required an analyst a full week can now be completed by AI in 30 minutes at a cost of approximately $1 (depending on the model and usage). A single such run may consume millions of tokens across search, synthesis, and reasoning processes.</p><p>This substitution effect is profound:</p><ul><li><strong>Token output becomes a new economic unit</strong> representing value creation.</li><li>As AI performs economically valuable tasks (research, analysis, coding, content creation), tokens effectively substitute digital labor.</li><li><strong>AI monetization is tokenized:</strong> Users purchase tokens to access AI capabilities, much like buying commodities. Companies such as OpenAI generate billions in revenue from token-based API usage.</li><li><strong>Blockchain integration:</strong> Some projects merge AI with crypto infrastructure. For example, Fetch.ai and SingularityNET use tokens (e.g., FET, AGIX) to pay for AI services on decentralized networks, forming a marketplace where AI agents "work" and are compensated in tokens.</li><li><strong>Efficiency incentives:</strong> Token-based pricing encourages optimization. Users learn to write concise prompts to reduce token consumption—similar to minimizing operational expenses. This dynamic drives innovation in efficiency and resource conservation.</li></ul><p>A genuine Token Economy is emerging. In the future, a portion of GDP may correlate with the volume of high-quality tokens generated and consumed—similar to how energy or compute capacity historically drove economic growth. Many technology leaders describe data centers as "token factories," where token-per-watt-per-dollar efficiency may directly influence socio-economic growth.</p><h2>AI Token Scale vs. Human Communication Scale</h2><p>Humanity collectively generates approximately 50 quadrillion tokens per year through spoken and written communication (estimated from average word counts, roughly 0.75–1 word per token).</p><figure><img src="/images/bai4-3.png" alt="Illustration 2" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><p>By comparison:</p><ul><li><strong>OpenAI</strong> processes hundreds of trillions to several quadrillion tokens annually, with API peaks reaching billions of tokens per minute and dozens of enterprise clients exceeding one trillion tokens per year.</li><li><strong>Google</strong> reported approximately 1.3 quadrillion tokens per month by late 2025 across Search, Gemini, and other services—surpassing many competitors.</li><li><strong>Individual scale:</strong> An average user may burn thousands of tokens per day via AI chat. With millions of users, global token burn can reach billions per hour.</li><li><strong>Enterprise scale:</strong> Training a model such as GPT-4 costs millions of dollars in electricity and consumes trillions of tokens from massive datasets. OpenAI reported that training GPT-3 alone cost approximately $4.6 million, with token burn estimated in the trillions.</li><li><strong>Environmental Impact:</strong> Each token requires electricity. Rough estimates suggest that 1,000 tokens may consume energy equivalent to powering an LED bulb for one hour. At global scale, AI token burn may account for 2–3% of worldwide electricity consumption—comparable to the aviation industry. Data centers operated by companies such as Google and Microsoft consume enormous energy volumes, raising legitimate climate concerns.</li></ul><p>AI systems are rapidly approaching—and in certain domains surpassing—the scale of total human communication processing. This is not merely a numerical milestone; it signals that machines are beginning to process information at a species-level magnitude.</p><p>Without aggressive optimization, uncontrolled token burn could bankrupt smaller AI startups, as GPU and electricity costs continue to escalate.</p>',
  'Tokens in AI: Understanding the "Currency" of Artificial Intelligence',
  'Explore what tokens are, why the term "Token Economy" matters, and who may emerge as the winners in this race.',
  NOW(), NOW()
FROM posts WHERE slug = 'token-trong-ai-hieu-ve-tien-te-cua-tri-tue-nhan-tao'
ON CONFLICT (post_id, locale) DO UPDATE SET
  title = EXCLUDED.title, slug = EXCLUDED.slug, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content;

INSERT INTO post_translations (post_id, locale, title, slug, excerpt, content, meta_title, meta_description, created_at, updated_at)
SELECT 
  id, 
  'en-US',
  'How to use Antigravity AI for Developers',
  'antigravity-ai-guide-for-developers',
  'A comprehensive guide on leveraging Antigravity to speed up your coding workflow.',
  '<p>Antigravity is an incredibly powerful AI coding assistant that acts like a real Developer right by your side.</p><h3>1. Launching Antigravity</h3><p>To get started, you need to install the Antigravity extension in VSCode. The highly intuitive interface allows you to communicate using natural language.</p><figure><img src="/images/antigravity_1.png" alt="Illustration 1" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><h3>2. Requesting Bug Fixes</h3><p>The most powerful feature of this AI is its ability to read your native Codebase. When a project throws an error, simply paste the error log, and the AI will automatically scan the files and suggest a fix.</p><figure><img src="/images/antigravity_2.png" alt="Illustration 2" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><h3>3. Automating Deployments</h3><p>If you aren’t familiar with GitHub Actions or Vercel, ask the AI to generate <code>.yml</code> scripts and configure server environments with just a single prompt.</p><p>Happy coding with Antigravity!</p>',
  'How to use Antigravity AI for Developers',
  'A comprehensive guide on leveraging Antigravity to speed up your coding workflow.',
  NOW(), NOW()
FROM posts WHERE slug = 'huong-dan-su-dung-ai-antigravity'
ON CONFLICT (post_id, locale) DO UPDATE SET
  title = EXCLUDED.title, slug = EXCLUDED.slug, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content;
